// Parse GPT response and build avatar configuration
const gptRaw = $input.first().json;
const transcript = $input.first().json.transcript || '';

let gptResponse;
try {
  gptResponse = JSON.parse(gptRaw.choices[0].message.content);
} catch(e) {
  gptResponse = {
    gloss: transcript,
    words_array: transcript.split(' '),
    sentiment: 'neutral',
    emotion: 'calm',
    topics: [],
    sign_intensity: 'medium',
    summary_arabic: transcript
  };
}

// Build avatar animation config
const avatarConfig = {
  expression: gptResponse.emotion,
  speed: gptResponse.emotion === 'excited' ? 1.4 :
         gptResponse.emotion === 'calm' ? 0.75 :
         gptResponse.emotion === 'sad' ? 0.85 : 1.0,
  gesture_intensity: gptResponse.sign_intensity || 'medium',
  eye_contact: true,
  facial_expressions: true,
  loop: false,
  background_style: gptResponse.sentiment === 'positive' ? 'warm' :
                   gptResponse.sentiment === 'negative' ? 'cool' : 'neutral'
};

// Build word-by-word animation sequence
const wordSequence = (gptResponse.words_array || []).map((word, index) => ({
  index: index,
  word: word,
  duration_ms: Math.max(500, word.length * 80),
  delay_ms: index * 600
}));

const jobId = 'job_' + Date.now() + '_' + Math.random().toString(36).substr(2,9);

return [{
  json: {
    job_id: jobId,
    status: 'processed',
    created_at: new Date().toISOString(),
    original_transcript: transcript,
    sign_gloss: gptResponse.gloss,
    words_array: gptResponse.words_array,
    word_sequence: wordSequence,
    sentiment: gptResponse.sentiment,
    emotion: gptResponse.emotion,
    topics: gptResponse.topics,
    summary_arabic: gptResponse.summary_arabic,
    avatar_config: avatarConfig,
    total_words: (gptResponse.words_array || []).length,
    estimated_duration_ms: (gptResponse.words_array || []).length * 600
  }
}];
